mapper.select:
select g.record_id, g.patient_id, g.research_id, g.follow_id, g.name, g.stage_num, g.stage_add_num,
g.question_status, g.question_time,
g.warn_status, g.over_time_status, g.over_time_handle_status, g.lose_type, g.lose_reason, g.update_by,
g.create_by, g.create_time, g.update_time,
g.fill_time, g.fill_status, g.visit_time, g.lock_visit_time, g.evaluate_status_back,
g.evaluate_prescription_back, g.evaluate_quality_back,
g.evaluate_reply_back, g.evaluate_reply_back_time, g.evaluate_status, g.evaluate_prescription,
g.evaluate_quality, g.evaluate_reply,
g.evaluate_reply_time, g.edc_status, g.follow_opinion, g.follow_status, g.follow_complete_time, g.ignore_type,
g.evaluate_status_back,g.evaluate_prescription_back,g.evaluate_quality_back,g.evaluate_reply_back,g.evaluate_reply_back_time,
g.over_evaluate_status_back,g.over_evaluate_prescription_back,g.over_evaluate_quality_back,g.over_evaluate_reply_back,g.over_evaluate_reply_back_time,
g.warn_evaluate_status_back,g.warn_evaluate_prescription_back,g.warn_evaluate_quality_back,g.warn_evaluate_reply_back,g.warn_evaluate_reply_back_time
from patient_record g
INNER JOIN patient_info p on p.patient_id = g.patient_id
INNER JOIN research_info i on i.id = p.research_id and i.del_flag = 0

    and g.patient_id = #{patientId}
    and g.research_id = #{researchId}
    and g.follow_id = #{followId}
    and g.name like concat('%', #{name}, '%')
    and g.stage_num = #{stageNum}
    and g.stage_add_num = #{stageAddNum}
    and g.question_status = #{questionStatus}
    and g.warn_status = #{warnStatus}
    and g.over_time_status = #{overTimeStatus}
    and g.over_time_handle_status =
        #{overTimeHandleStatus}

    and g.fill_time = #{fillTime}
    and g.visit_time = #{visitTime}
    and p.enrollment_handler_status = #{enrollmentHandlerStatus}

select g.record_id, g.patient_id, g.research_id, g.follow_id, g.name, g.stage_num, g.stage_add_num,
g.warn_status, g.over_time_status, g.over_time_handle_status, g.create_time, g.edc_status, g.follow_status
from patient_record g
INNER JOIN patient_info p on p.patient_id = g.patient_id
INNER JOIN research_info i on i.id = p.research_id and i.del_flag = 0
INNER JOIN patient_record_template prt on prt.follow_id = g.follow_id
where prt.follow_num > 0
and g.patient_id = #{patientId}
and g.research_id = #{researchId}
and g.follow_id = #{followId}
and g.name like concat('%', #{name}, '%')
and g.stage_num = #{stageNum}
and g.stage_add_num = #{stageAddNum}
and g.question_status = #{questionStatus}
and g.warn_status = #{warnStatus}
and g.over_time_status = #{overTimeStatus}
and g.over_time_handle_status =
    #{overTimeHandleStatus}

and p.enrollment_handler_status = #{enrollmentHandlerStatus}

select p.patient_id, p.patient_name, p.enrollment_time, i.project_name, r.name, r.create_time, r.record_id, ac.mobile, r.research_id, r.question_time, r.follow_complete_time, r.follow_submit_time,r.stage_add_num ,r.over_time_handle_status,r.over_time_handle_time,p.person_id,r.fill_status,r.form_complent_rate FROM patient_record r INNER JOIN patient_info p on p.patient_id = r.patient_id INNER JOIN research_info i on i.id = p.research_id INNER JOIN patient_record_template prt on prt.follow_id = r.follow_id INNER JOIN patient_account ac on p.account_id=ac.account_id where prt.follow_num = 0 AND i.del_flag = '0'
and r.research_id = #{researchId} and r.follow_status = #{followStatus} and r.warn_status = #{warnStatus} and r.over_time_status = #{overTimeStatus} and p.patient_name like concat('%', #{patientName}, '%')
and p.patient_id like concat('%', #{patientId}, '%') and p.person_id like concat('%', #{personId}, '%') and p.enrollment_handler_status = #{enrollmentHandlerStatus} and p.enrollment_status = #{enrollmentStatus}
and date(p.enrollment_time) >= #{enrollmentStartTime}
and #{enrollmentEndTime} >= date(p.enrollment_time)

select p.patient_id, p.patient_name, p.enrollment_time, i.project_name, r.name, r.create_time, r.record_id,
ac.mobile,
r.research_id, r.question_time, r.follow_complete_time, r.follow_submit_time,r.stage_add_num,
r.over_time_create_time
,r.over_time_handle_status,r.over_time_handle_time,p.person_id,r.fill_status,r.create_by,r.form_complent_rate, prt.follow_num
FROM patient_record r
INNER JOIN patient_info p on p.patient_id = r.patient_id
INNER JOIN research_info i on i.id = p.research_id
INNER JOIN patient_record_template prt on prt.follow_id = r.follow_id
INNER JOIN patient_account ac on p.account_id=ac.account_id
where prt.follow_num > 0 AND i.del_flag = '0'
and p.research_id not in (select DISTINCT(q.research_id) from quit_record q where q.is_agree = 1 and
q.research_id = p.research_id and q.person_id = p.person_id)

and r.research_id = #{researchId}


        ${followStatusSql}


        and r.follow_status = #{followStatus}


and p.patient_status != 4
and r.warn_status = #{warnStatus}
and r.over_time_status = #{overTimeStatus}


        #{item}


and r.evaluate_status = #{evaluateStatus}
and r.fill_status = #{fillStatus}
and p.patient_name like concat('%', #{patientName},
    '%')

and p.patient_id like concat('%', #{patientId}, '%')
and p.person_id like concat('%', #{personId}, '%')
and p.enrollment_handler_status = #{enrollmentHandlerStatus}
and r.name = #{stageName}
and date(p.enrollment_time) >=
    #{enrollmentStartTime}

and #{enrollmentEndTime} >=
    date(p.enrollment_time)

select r.research_id
FROM patient_record r
INNER JOIN patient_info p on p.patient_id = r.patient_id
INNER JOIN patient_record_template prt on prt.follow_id = r.follow_id
where prt.follow_num > 0
and r.research_id = #{researchId}
and r.follow_status = #{followStatus}
and r.warn_status = #{warnStatus}
and r.over_time_status = #{overTimeStatus}
and p.patient_name like concat('%', #{patientName},
    '%')

and p.patient_id like concat('%', #{patientId}, '%')
and p.enrollment_handler_status = #{enrollmentHandlerStatus}

select p.patient_id, p.patient_name, i.project_name, r.name, r.create_time,
r.record_id,r.evaluate_reply_back_time,r.evaluate_reply_time,
r.warn_evaluate_reply_back_time,r.over_evaluate_reply_back_time
from patient_record r, patient_info p, research_info i
where i.id=p.research_id and p.patient_id=r.patient_id and p.patient_activity_status = '1'
and r.research_id = #{researchId}
and r.follow_status
    in('3','4') and r.evaluate_status_back = #{evaluateStatus}

and r.follow_status
    in('3','4') and r.evaluate_status = #{evaluateStatus}

and r.over_time_status
    in('3','4') and r.over_evaluate_status_back = #{evaluateStatus}

and r.warn_status
    in('3','4') and r.warn_evaluate_status_back = #{evaluateStatus}

and p.patient_id = #{patientId}
and p.patient_name like concat('%', #{patientName},
    '%')

SELECT re.*
FROM patient_record re
         JOIN (SELECT MAX(record_id) AS max_id
               FROM patient_record
               WHERE patient_id = #{patientId}
                 AND research_id = #{researchId}) max_rec ON re.record_id = max_rec.max_id
WHERE re.patient_id = #{patientId}
  AND re.research_id = #{researchId};

SELECT re.*, b.edcNames
FROM patient_record re
         LEFT JOIN (SELECT patient_id, GROUP_CONCAT(name) AS edcNames
                    FROM patient_record
                    WHERE patient_id = #{patientId}
                      AND research_id = #{researchId}
                      AND edc_status = '4') b ON re.patient_id = b.patient_id
WHERE re.patient_id = #{patientId}
  AND re.research_id = #{researchId}
  AND re.record_id = (SELECT MAX(record_id)
                      FROM patient_record
                      WHERE patient_id = #{patientId}
                        AND research_id = #{researchId});

mapper.update:
update patient_record
set edc_status = #{edcStatus}
where record_id = #{recordId}

mapper.select:
select p.patient_id,p.patient_name, r.record_id ,p.dept_id,r.warn_status,r.over_time_create_time,p.research_id
from patient_record r, patient_info p, research_info i ,patient_record_template prt
where i.id=p.research_id and p.patient_id=r.patient_id and prt.follow_id=r.follow_id and prt.follow_num>0
and i.del_flag = '0'
and p.research_id = #{researchId}
and p.dept_id = #{deptId}
and p.enrollment_handler_status = #{enrollmentHandlerStatus}

select g.record_id, g.patient_id, g.research_id,
g.evaluate_prescription_back, g.evaluate_quality_back,
g.evaluate_prescription, g.evaluate_quality, g.follow_status,g.follow_opinion_user_id,
g.follow_id,g.lock_visit_time,g.stage_add_num
from patient_record g
inner join patient_info pi on g.patient_id = pi.patient_id
inner join research_info ri on g.research_id=ri.id

    and g.follow_status = #{followStatus}
    and g.follow_id = #{followId}
    and g.patient_id = #{patientId}
    and g.over_time_status = #{overTimeStatus}
    and g.follow_opinion_user_id = #{followOpinionUserId}
    and TO_DAYS(g.follow_complete_time) >= TO_DAYS(#{startTime})
    and TO_DAYS(g.follow_complete_time) <= TO_DAYS(#{endTime})

mapper.delete:
delete
from patient_record
where research_id = #{researchId}
  and patient_id = #{patientId}
  and follow_id = #{followId}

mapper.update:
update patient_record
set visit_time      = #{visitTime},
    lock_visit_time = #{visitTime}
where research_id = #{id}

mapper.sql:
select COUNT(patientRecord.record_id) from patient_record patientRecord
LEFT JOIN patient_info patientInfo ON patientInfo.patient_id = patientRecord.patient_id
LEFT JOIN research_info researchInfo on researchInfo.id = patientInfo.research_id
LEFT JOIN research_diseases researchDiseases ON researchDiseases.disease_id = researchInfo.disease_type_id
where patientRecord.name != '基线' and patientInfo.patient_status != 6

    AND patientInfo.dept_id = #{deptId}


    AND researchInfo.id = #{researchId}


    AND researchDiseases.disease_id = #{diseaseId}
